import sys
from functools import lru_cache

# 4 distinct hook orientations (rotations; shape has horizontal reflection symmetry)
# Canonical: 
# XXX
# X.X
# ..X
ORIENTATIONS = [
    {(0,0),(0,1),(0,2),(1,0),(1,2),(2,2)},  # 0 deg
    {(0,1),(0,2),(1,2),(2,0),(2,1),(2,2)},  # 90 deg CW
    {(0,0),(1,0),(1,2),(2,0),(2,1),(2,2)},  # 180 deg
    {(0,0),(0,1),(0,2),(1,1),(2,0),(2,2)},  # 270 deg CW
]

def solve(m, n):
    """Check if m x n rectangle can be tiled by hooks using backtracking."""
    if (m * n) % 6 != 0:
        return False
    if m < 3 or n < 3:
        return False

    grid = [[False]*n for _ in range(m)]

    # Find first uncovered cell
    def find_first():
        for i in range(m):
            for j in range(n):
                if not grid[i][j]:
                    return (i, j)
        return None

    def backtrack():
        cell = find_first()
        if cell is None:
            return True
        r, c = cell
        # Try placing each orientation with (r,c) as top-left corner
        # The first uncovered cell must be covered, so we try orientations
        # where (r,c) is part of the hook. The hook's top-left is at (r-dr, c-dc)
        # for some (dr,dc) in the orientation.
        for orient in ORIENTATIONS:
            for (dr, dc) in orient:
                tr, tc = r - dr, c - dc  # top-left of 3x3 bounding box
                if tr < 0 or tc < 0 or tr + 2 >= m or tc + 2 >= n:
                    continue
                # Check all cells are valid and uncovered
                cells = [(tr+odr, tc+odc) for (odr,odc) in orient]
                if all(0 <= cr < m and 0 <= cc < n and not grid[cr][cc] for cr,cc in cells):
                    # Place hook
                    for cr, cc in cells:
                        grid[cr][cc] = True
                    if backtrack():
                        return True
                    # Remove hook
                    for cr, cc in cells:
                        grid[cr][cc] = False
        return False

    return backtrack()

# Check all m x n with 3 <= m <= n <= 20, 6 | mn
results = {}
for m in range(3, 21):
    for n in range(m, 21):
        if (m * n) % 6 != 0:
            continue
        result = solve(m, n)
        results[(m,n)] = result
        print(f"{m}x{n}: {'YES' if result else 'NO'}")
